(input) => {
  const state = input.state || { checkpoint: { x: 0, y: 1, z: 3 }, saved: false, finished: false };
  for (const event of input.events) {
    if (event.kind === 'win') state.finished = true;
    if (event.kind === 'trigger' && event.event === 'checkpoint') {
      state.saved = true;
      state.checkpoint = { x: 0, y: 1, z: -7 };
    }
  }
  const commands = [];
  if (input.entity.position.y < -8 || input.justPressed.includes('respawn')) {
    commands.push({ kind: 'teleport', position: state.checkpoint });
  }
  commands.push({ kind: 'hud', id: 'title', text: 'RELAY YARD', x: 24, y: 32, size: 26, color: '#eef5ff' });
  commands.push({ kind: 'hud', id: 'score', text: state.finished ? 'Course complete' : 'Collect the two amber cells', x: 24, y: 61, size: 17, color: '#ffd273' });
  commands.push({ kind: 'hud', id: 'win', text: state.finished ? 'Explore the test lanes, or Reset to run again.' : 'Follow the amber line through the blue gate.', x: 24, y: 86, size: 14, color: '#c1d4ea' });
  commands.push({ kind: 'hud', id: 'checkpoint-status', text: state.saved ? 'CHECKPOINT SAVED' : 'CHECKPOINT AHEAD', x: 936, y: 32, size: 14, align: 'right', color: '#67e7c5' });
  commands.push({ kind: 'hud', id: 'stations', text: 'LEFT: STEPS + LIFT     RIGHT: RAMP + CRATE', x: 480, y: 475, size: 14, align: 'center', color: '#c1d4ea' });
  commands.push({ kind: 'hud', id: 'help', text: 'WASD / arrows: move     Space: jump     R: respawn     Drag: camera', x: 480, y: 510, size: 15, align: 'center', color: '#eef5ff' });
  return { state, commands };
}

